// Occupational Therapy Practice Test 1. Original questions written for Valus from the HOSA 2026–27 test
// plan, slightly harder than the sample items: models of practice and occupation-based problem solving.
import {q, mix} from './q.js';
const OB='O’Brien & Conners, Introduction to Occupational Therapy', AD='Atchison & Dirette, Conditions in Occupational Therapy';
const PROF='Profession of OT', MOD='Occupational Therapy Models of Practice', ACT='Activity Analysis and Occupation-based Activities', PHYS='Occupational Therapy for Physical Conditions', MH='Occupational Therapy for Wellness and Mental Health', LIFE='Occupational Therapy Across the Lifespan: Children, Adults, Older Adults', ETH='Ethical and Safety Considerations';

export default {
 id:'occupational-therapy-1',
 event:'Occupational Therapy',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'O’Brien & Conners’ Introduction to Occupational Therapy and Atchison & Dirette’s Conditions in Occupational Therapy',
 plan:[{area:PROF,weight:10},{area:MOD,weight:10},{area:ACT,weight:10},{area:PHYS,weight:20},{area:MH,weight:20},{area:LIFE,weight:20},{area:ETH,weight:10}],
 questions:mix([
  q(PROF,'What is the central focus of occupational therapy?','Enabling meaningful daily activities',['Prescribing medication for pain','Diagnosing medical conditions','Performing surgery on injured limbs'],'B','OT enables participation in occupations, the everyday activities people need and want to do, such as self-care, work, school and leisure.',OB),
  q(PROF,'Which organization certifies occupational therapists and OT assistants after they pass a national exam?','NBCOT',['AOTA','APTA','ACOTE'],'D','The National Board for Certification in Occupational Therapy grants the OTR and COTA credentials. AOTA is the professional association.',OB),
  q(PROF,'Managing money, shopping and caring for others are examples of which type of occupation?','Instrumental activities of daily living',['Basic activities of daily living','Rest and sleep routines','Play'],'A','IADLs are complex tasks needed to live independently in the community. Basic ADLs include bathing, dressing, eating and toileting.',OB),
  q(PROF,'Which early OT leader developed “habit training” for people with mental illness?','Eleanor Clarke Slagle',['Florence Nightingale','Clara Barton','Mary Reilly'],'C','Slagle created habit training, which used structured daily routines, and was a founder of the profession in 1917.',OB),
  q(PROF,'How does the education of an occupational therapy assistant usually differ from that of an occupational therapist?','OTAs complete an associate degree; OTs a master’s or doctorate',['OTAs complete a doctorate; OTs an associate degree','Both require a medical degree','Neither requires a college degree'],'B','OTs enter with a master’s or doctoral degree. OTAs usually earn an associate degree and work under OT supervision.',OB),
  q(MOD,'The Model of Human Occupation (MOHO) describes which three parts of a person?','Volition, habituation and performance capacity',['Id, ego and superego','Body, mind and spirit','Strength, range of motion and endurance'],'D','MOHO looks at motivation (volition), habits and roles (habituation) and physical and mental abilities (performance capacity).',OB),
  q(MOD,'The Person-Environment-Occupation (PEO) model explains occupational performance as:','The person–environment–occupation fit',['A result of strength alone','The person’s diagnosis','The opinions of the client’s family members'],'A','Better fit among the three components leads to better performance, so OT may change the task or environment as well as the person’s skills.',OB),
  q(MOD,'An OT focuses on improving a patient’s range of motion, strength and endurance after a hand injury. Which frame of reference is this?','Biomechanical',['Psychodynamic','Sensory integration','Cognitive disabilities'],'C','The biomechanical frame of reference addresses the physical capacities needed for movement, such as ROM, strength and endurance.',OB),
  q(MOD,'Which frame of reference, developed by A. Jean Ayres, addresses how the brain processes and organizes sensory input?','Sensory integration',['Biomechanical','Rehabilitative','Behavioral learning'],'B','Ayres Sensory Integration uses play-based sensory experiences to help children process and respond to sensory information.',OB),
  q(MOD,'A patient with permanent weakness learns to dress using a reacher and sock aid. Which approach is this?','Rehabilitative (compensatory)',['Biomechanical (restorative)','Sensory integration','Psychodynamic'],'D','The rehabilitative approach teaches compensation with adaptive equipment and new methods when abilities cannot be fully restored.',OB),
  q(ACT,'What is activity analysis?','Breaking a task into its demands',['Measuring a patient’s vital signs','Writing the discharge summary','Choosing a patient’s diagnosis'],'A','Activity analysis examines the steps, skills, tools and environment an activity requires so the OT can choose, adapt or grade it.',OB),
  q(ACT,'An OT gradually increases the number of buttons a patient fastens each session. What is this called?','Grading the activity',['Adapting the environment','Activity analysis','Discharge planning'],'C','Grading changes the demands of an activity step by step to make it more or less challenging as the client improves.',OB),
  q(ACT,'A patient with arthritis has a weak grip. Which adaptation helps with eating?','Utensils with built-up handles',['Thinner utensils','Heavier ceramic plates','Removing utensils entirely'],'B','Built-up handles need less finger flexion and grip strength, making utensils easier to hold.',OB),
  q(ACT,'Squeezing therapy putty to strengthen the hand before practicing buttoning is an example of:','A preparatory activity',['An occupation-based activity','An instrumental ADL','A leisure occupation'],'D','Preparatory methods ready the client for occupation. Practicing the actual task, such as buttoning a shirt for work, is occupation-based.',OB),
  q(ACT,'Making a sandwich requires following steps in the right order. Which skill is this?','Sequencing',['Proprioception','Bilateral coordination only','Visual acuity'],'A','Sequencing is a cognitive skill. Activity analysis identifies such demands so the OT can address them.',OB),
  q(PHYS,'A patient with left neglect after a right-brain stroke ignores items on the left side. Which strategy encourages scanning?','Placing items on the left with cues',['Placing everything on the right side','Covering the patient’s left eye','Ignoring the neglect'],'C','Visual scanning training and cueing help patients attend to the neglected side. Placing everything on the right side compensates but does not train awareness.',AD),
  q(PHYS,'A patient with a C6 spinal cord injury can extend the wrist but not move the fingers. Which technique lets him grasp objects?','Tenodesis grasp',['Lateral pinch with finger flexors','Power grip','Three-jaw chuck'],'B','Extending the wrist passively closes the fingers (tenodesis), allowing a functional grasp. Splints can enhance it.',AD),
  q(PHYS,'After a posterior hip replacement, which device helps a patient put on socks without breaking hip precautions?','Sock aid',['Weighted utensil','Rocker knife','Universal cuff'],'D','A sock aid lets the patient put on socks without bending the hip past 90 degrees. Reachers and long-handled shoehorns are also used.',AD),
  q(PHYS,'Which joint protection principle is taught to people with rheumatoid arthritis?','Use larger, stronger joints to do tasks',['Grip objects tightly with the fingers','Hold one position for long periods','Twist lids with the fingers'],'A','Using larger joints (such as carrying a bag on the forearm) reduces stress on small, inflamed joints.',AD),
  q(PHYS,'How is the wrist positioned in a splint for carpal tunnel syndrome?','In a neutral position',['Fully flexed','Fully extended','Bent to the thumb side'],'C','A neutral wrist position creates the most space in the carpal tunnel, reducing pressure on the median nerve, especially at night.',AD),
  q(PHYS,'A patient with COPD gets short of breath while grooming. Which energy conservation strategy helps?','Sitting down to groom',['Standing and rushing to finish','Holding the breath while brushing','Grooming right after a large meal'],'B','Sitting reduces energy use. Other strategies include planning, pacing, organizing supplies and pursed-lip breathing.',AD),
  q(PHYS,'A patient with memory loss after a brain injury forgets daily tasks. Which strategy helps?','A memory notebook or phone reminders',['Testing memory repeatedly without aids','Removing all calendars','Avoiding routines'],'D','External memory aids compensate for impaired memory and support independence.',AD),
  q(PHYS,'A patient with Parkinson’s disease has a tremor that makes eating difficult. Which adaptation may help?','Weighted utensils',['Lighter plastic forks','Longer chopsticks','Eating standing up'],'A','Added weight dampens tremor movement, making it easier to bring food to the mouth.',AD),
  q(PHYS,'Which home change helps a client with low vision?','Using high-contrast colors and good lighting',['Dimming all the lights at home','Using white plates on a white table','Removing labels from items'],'C','High contrast, bright even lighting and large print help people with low vision find and use items safely.',AD),
  q(PHYS,'A stroke survivor’s weak shoulder hangs and partly slips out of the joint. Which approach helps protect it?','Supporting the arm on a lapboard',['Pulling on the arm during transfers','Letting the arm hang freely','Lifting the patient by the arm'],'B','Shoulder subluxation is common after stroke. Supporting the arm and avoiding pulling on it reduce pain and further injury.',AD),
  q(MH,'How can OT help a client with depression who has stopped most daily activities?','By rebuilding a meaningful routine',['By encouraging the client to stay in bed','By removing all responsibilities','By focusing only on medication'],'D','Structured routines and engaging, achievable activities can improve mood, motivation and a sense of competence.',AD),
  q(MH,'Which intervention helps a client with schizophrenia prepare to live in the community?','Social and living skills training',['Long periods of isolation','Avoiding all daily routines','Only passive range of motion'],'A','Skills such as conversation, money management, cooking and using transportation support community living.',AD),
  q(MH,'A teen with anxiety becomes overwhelmed in noisy settings. Which OT approach may help?','Teaching sensory coping strategies',['Requiring the teen to stay in loud rooms longer','Removing all coping tools','Avoiding discussion of triggers'],'C','Sensory modulation strategies help people regulate their arousal and manage anxiety.',AD),
  q(MH,'Which assessment estimates a person’s cognitive functioning level to guide safe task demands?','Allen Cognitive Levels',['Borg scale','Berg Balance Scale','Goniometry testing'],'B','Allen’s Cognitive Disabilities model rates cognitive levels so the OT can match activities and environments to the person’s abilities.',OB),
  q(MH,'Which strategy is commonly taught to help clients manage anxiety in daily life?','Relaxation techniques such as deep breathing',['Avoiding all activities that cause stress','Drinking more caffeine','Skipping meals to stay alert'],'D','Relaxation, coping skills and graded exposure to feared activities help clients function. Total avoidance tends to increase anxiety.',AD),
  q(MH,'For a client recovering from substance use, what is a key OT goal?','Building new routines and roles',['Spending more time alone','Returning to old social habits','Avoiding all work'],'A','Substance use often fills time and roles. Building healthy routines, roles and interests supports long-term recovery.',AD),
  q(MH,'The Well Elderly Study found that older adults who took part in an occupation-based “lifestyle redesign” program:','Showed better health and well-being',['Had more falls and injuries','Lost interest in activities','Needed more medication'],'C','Lifestyle Redesign helped older adults build healthy routines and meaningful activity, improving quality of life and health.',OB),
  q(MH,'How might an OT support a client in eating disorder treatment?','By practicing meal planning and cooking',['By avoiding all discussion of food','By encouraging skipped meals','By focusing only on daily exercise'],'B','OT helps clients rebuild healthy relationships with food through meal planning, grocery shopping and cooking, often within a team approach.',AD),
  q(MH,'What does trauma-informed care emphasize?','Safety, trust and client choice',['Requiring clients to describe their trauma','Using physical restraint first','Making all decisions for the client'],'D','Trauma-informed care recognizes the effects of trauma and avoids retraumatizing clients by emphasizing safety, collaboration and empowerment.',AD),
  q(MH,'How can an OT help a person with moderate dementia complete self-care?','Simplify and give one-step cues',['Give many choices at once','Rearrange the home often','Use long verbal explanations'],'A','A simple, consistent environment and short, step-by-step cues reduce confusion and support independence.',AD),
  q(LIFE,'By about what age do most children use a mature tripod grasp on a pencil?','4–6 years',['1 year','2 years','10 years'],'C','Grasp develops from a palmar grasp in toddlers to a mature tripod grasp around ages 4–6.',OB),
  q(LIFE,'A child refuses to touch finger paint, sand or certain clothing textures. What might this suggest?','Tactile defensiveness',['Poor visual acuity','Hearing loss','Low muscle tone only'],'B','Tactile defensiveness is an over-response to touch, a type of sensory processing difficulty that OT can address.',OB),
  q(LIFE,'Which tool often helps children with autism manage transitions during the school day?','A visual schedule',['Unexpected changes in routine','Long verbal instructions','Louder classrooms'],'D','Visual schedules make the day predictable and reduce anxiety about transitions.',AD),
  q(LIFE,'A child has trouble planning and carrying out new motor tasks, such as tying shoes or riding a bike. Which condition is this?','Developmental coordination disorder',['Spastic diplegic cerebral palsy','Down syndrome with hypotonia','Spina bifida occulta'],'A','DCD (dyspraxia) affects motor planning and coordination without another neurological cause. OT uses task-oriented practice.',AD),
  q(LIFE,'In public schools, OT services for a student with a disability are written into which document?','The IEP',['A hospital discharge plan','A Medicare claim form','The student’s report card'],'C','Under IDEA, the IEP lists goals and related services, such as OT, that help the student benefit from education.',OB),
  q(LIFE,'Which tool may help a student who struggles with handwriting posture and control?','A slant board',['A heavier backpack','A smaller desk','Removing the student’s pencil'],'B','A slanted writing surface positions the wrist in extension, which can improve control and reduce fatigue.',OB),
  q(LIFE,'An OT evaluates an office worker’s desk setup to prevent repetitive strain. What is this area of practice?','Ergonomics',['Sensory integration','Driver rehabilitation','Feeding therapy'],'D','Ergonomic changes, such as chair height, keyboard position and breaks, reduce strain and prevent work injuries.',OB),
  q(LIFE,'Which home change most reduces bathroom fall risk for an older adult?','Installing grab bars by the toilet and tub',['Adding throw rugs on wet floors','Using dim night lighting','Removing the shower chair'],'A','Grab bars, nonslip mats, shower chairs and good lighting support safe bathing and toileting.',OB),
  q(LIFE,'An OT specialist evaluates whether an older adult with mild cognitive changes can safely continue to drive. What is this service?','Driver rehabilitation',['Work hardening','Hippotherapy','Constraint-induced therapy'],'C','Driver rehab assessments look at vision, cognition, reaction time and motor skills, and may recommend vehicle changes or training.',OB),
  q(LIFE,'What does “aging in place” mean?','Staying safely in one’s own home with age',['Moving to a nursing home early','Staying in a hospital long term','Living in a different place each year'],'B','OTs support aging in place with home modifications, adaptive equipment and routines that keep older adults independent.',OB),
  q(ETH,'Which document guides the ethical conduct of occupational therapy practitioners?','The AOTA Code of Ethics',['The Hippocratic Oath only','The Nuremberg Code','State traffic laws'],'D','The AOTA Code of Ethics includes principles such as beneficence, nonmaleficence, autonomy, justice, veracity and fidelity.',OB),
  q(ETH,'Before transferring a client from a wheelchair, what should the OT do first?','Lock the wheelchair brakes',['Remove the client’s shoes','Lift the client by the arms','Turn the wheelchair sideways'],'A','Locking the brakes keeps the chair from rolling. A gait belt and proper body mechanics also make transfers safer.',OB),
  q(ETH,'Shared therapy equipment such as therapy putty and adaptive tools should be:','Cleaned between clients',['Shared without cleaning','Cleaned once a month by housekeeping','Used only by staff'],'C','Standard infection control requires cleaning and disinfecting shared equipment, or issuing items for single-client use.',OB),
  q(ETH,'What is the supervision relationship between an OT and an OTA?','The OTA works under OT supervision',['The OT works under the OTA','They never work together with clients','The OTA supervises the OT'],'B','The OT is responsible for evaluation and the intervention plan. The OTA provides services under the OT’s supervision, as defined by state law.',OB),
  q(ETH,'An OT discusses a client’s progress with a friend at a restaurant. What principle is violated?','Confidentiality',['Nonmaleficence','Autonomy','Justice'],'D','Client information is shared only with those involved in care or with the client’s permission. Discussing it in public violates privacy and ethics codes.',OB)
 ],103)
};
